-- StoryChurch Auction — complete database setup for a NEW, EMPTY Supabase project.
-- Generated by `npm run db:bundle` from db/migrations/*.sql. Run it ONCE:
--   Supabase dashboard → SQL Editor → New query → paste this whole file → Run.
-- It creates the tables, protections, and turns on row-level security everywhere
-- (the public API key can read or write nothing; only the server can).
-- It creates NO demo data.

create table if not exists schema_migrations (name text primary key, applied_at timestamptz not null default now());
alter table schema_migrations enable row level security;

-- ════════════ 0001_init.sql ════════════
-- StoryChurch Auction — initial schema.
-- Plain PostgreSQL 14+: runs unchanged on local Postgres and on Supabase.
-- All money is stored as integer cents. All timestamps are timestamptz (UTC).

-- ───────────────────────── events ─────────────────────────
create table events (
  id                       uuid primary key default gen_random_uuid(),
  name                     text not null,
  event_date               date,
  timezone                 text not null default 'America/Denver',
  silent_start_at          timestamptz,
  silent_close_at          timestamptz,
  default_increment_cents  integer not null default 500 check (default_increment_cents > 0),
  pickup_instructions      text not null default '',
  contact_info             text not null default '',
  next_bidder_number       integer not null default 1001,
  is_demo                  boolean not null default false,
  created_at               timestamptz not null default now()
);

-- ───────────────────────── staff ─────────────────────────
create table admin_users (
  id             uuid primary key default gen_random_uuid(),
  email          text not null,
  name           text not null,
  password_hash  text not null,
  role           text not null default 'volunteer' check (role in ('admin', 'volunteer')),
  active         boolean not null default true,
  created_at     timestamptz not null default now()
);
create unique index admin_users_email_uq on admin_users (lower(email));

create table admin_sessions (
  token_hash  text primary key,
  admin_id    uuid not null references admin_users(id) on delete cascade,
  expires_at  timestamptz not null,
  created_at  timestamptz not null default now()
);

-- ───────────────────────── bidders ─────────────────────────
create table bidders (
  id                       uuid primary key default gen_random_uuid(),
  event_id                 uuid not null references events(id),
  bidder_number            integer not null,           -- also the physical paddle number
  name                     text not null check (length(trim(name)) > 0),
  phone                    text,                        -- normalized E.164 (+1XXXXXXXXXX)
  email                    text,                        -- lower-cased
  assisted                 boolean not null default false,
  registered_by_admin_id   uuid references admin_users(id),
  verified_at              timestamptz,
  created_at               timestamptz not null default now(),
  updated_at               timestamptz not null default now(),
  constraint bidders_contact_chk check (assisted or phone is not null or email is not null),
  constraint bidders_number_uq unique (event_id, bidder_number)
);
create unique index bidders_phone_uq on bidders (event_id, phone) where phone is not null;
create unique index bidders_email_uq on bidders (event_id, email) where email is not null;
create index bidders_name_idx on bidders (event_id, lower(name));

create table bidder_sessions (
  token_hash  text primary key,
  bidder_id   uuid not null references bidders(id) on delete cascade,
  expires_at  timestamptz not null,
  created_at  timestamptz not null default now()
);
create index bidder_sessions_bidder_idx on bidder_sessions (bidder_id);

create table verification_codes (
  id             uuid primary key default gen_random_uuid(),
  event_id       uuid not null references events(id),
  contact_type   text not null check (contact_type in ('phone', 'email')),
  contact_value  text not null,
  name           text,                 -- name supplied at registration (null for plain sign-in)
  code_hash      text not null,
  attempts       integer not null default 0,
  expires_at     timestamptz not null,
  consumed_at    timestamptz,
  created_at     timestamptz not null default now()
);
create index verification_codes_contact_idx on verification_codes (contact_value, created_at desc);

-- ───────────────────────── items ─────────────────────────
create table auction_items (
  id                  uuid primary key default gen_random_uuid(),
  event_id            uuid not null references events(id),
  item_number         integer not null,
  kind                text not null check (kind in ('silent', 'live')),
  title               text not null check (length(trim(title)) > 0),
  description         text not null default '',
  image_path          text,
  donor_name          text,
  starting_bid_cents  integer not null default 0 check (starting_bid_cents >= 0),
  increment_cents     integer not null default 500 check (increment_cents > 0),
  -- draft: hidden · upcoming: visible, not yet biddable · open · paused · closed · finalized
  status              text not null default 'open'
                        check (status in ('draft', 'upcoming', 'open', 'paused', 'closed', 'finalized')),
  closes_at           timestamptz,       -- silent override; null → events.silent_close_at
  live_order          integer,           -- position in the live program
  -- denormalised leader, maintained inside the same transaction as each bid
  current_bid_cents   integer,
  current_bidder_id   uuid references bidders(id),
  bid_count           integer not null default 0,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint auction_items_number_uq unique (event_id, item_number)
);
-- Only one live item may be on the block (open or paused) at a time.
create unique index one_live_item_on_block
  on auction_items (event_id) where kind = 'live' and status in ('open', 'paused');
create index auction_items_event_kind_idx on auction_items (event_id, kind, item_number);

-- ───────────────────────── silent bids ─────────────────────────
create table silent_bids (
  id                    uuid primary key default gen_random_uuid(),
  item_id               uuid not null references auction_items(id),
  bidder_id             uuid not null references bidders(id),
  amount_cents          integer not null check (amount_cents > 0),
  placed_by_admin_id    uuid references admin_users(id),   -- set for assisted bids
  idempotency_key       text not null,
  created_at            timestamptz not null default now(),
  constraint silent_bids_idem_uq unique (bidder_id, idempotency_key),
  constraint silent_bids_amount_uq unique (item_id, amount_cents)  -- DB backstop: no equal bids
);
create index silent_bids_item_amount_idx on silent_bids (item_id, amount_cents desc);
create index silent_bids_bidder_idx on silent_bids (bidder_id);

-- ───────────────────────── live auction ─────────────────────────
create table live_bid_requests (
  id                    uuid primary key default gen_random_uuid(),
  item_id               uuid not null references auction_items(id),
  bidder_id             uuid not null references bidders(id),
  amount_cents          integer not null check (amount_cents > 0),
  status                text not null default 'pending'
                          check (status in ('pending', 'accepted', 'rejected', 'superseded', 'expired')),
  idempotency_key       text not null,
  resolved_by_admin_id  uuid references admin_users(id),
  resolved_at           timestamptz,
  resolution_note       text,
  created_at            timestamptz not null default now(),
  constraint live_requests_idem_uq unique (bidder_id, idempotency_key)
);
create unique index one_pending_request_per_bidder_item
  on live_bid_requests (item_id, bidder_id) where status = 'pending';
create index live_requests_item_idx on live_bid_requests (item_id, created_at);

create table live_accepted_bids (
  id                    uuid primary key default gen_random_uuid(),
  item_id               uuid not null references auction_items(id),
  seq                   integer not null,
  bidder_id             uuid not null references bidders(id),
  amount_cents          integer not null check (amount_cents > 0),
  source                text not null check (source in ('paddle', 'mobile')),
  request_id            uuid unique references live_bid_requests(id),
  entered_by_admin_id   uuid not null references admin_users(id),
  created_at            timestamptz not null default now(),
  constraint live_accepted_seq_uq unique (item_id, seq)
  -- amount ordering is enforced transactionally (amount must exceed the current non-voided bid);
  -- no unique(amount) because a voided bid's amount may be legitimately re-entered.
);
create index live_accepted_item_idx on live_accepted_bids (item_id, seq desc);

-- Accepted bids are immutable; a clerk's mistake is recorded as a void row instead.
create table live_bid_voids (
  accepted_bid_id  uuid primary key references live_accepted_bids(id),
  voided_by        uuid not null references admin_users(id),
  reason           text not null,
  created_at       timestamptz not null default now()
);

-- ───────────────────────── results & money ─────────────────────────
create table winning_results (
  id                    uuid primary key default gen_random_uuid(),
  item_id               uuid not null references auction_items(id),
  bidder_id             uuid not null references bidders(id),
  amount_cents          integer not null check (amount_cents > 0),
  source                text not null check (source in ('silent_bid', 'live_bid')),
  source_bid_id         uuid not null,
  finalized_by_admin_id uuid references admin_users(id),  -- null = automatic finalization at the silent closing time
  finalized_at          timestamptz not null default now(),
  voided_at             timestamptz,
  voided_by_admin_id    uuid references admin_users(id),
  void_reason           text
);
create unique index winning_results_one_active on winning_results (item_id) where voided_at is null;
create index winning_results_bidder_idx on winning_results (bidder_id) where voided_at is null;

create table payments (
  id                   uuid primary key default gen_random_uuid(),
  event_id             uuid not null references events(id),
  bidder_id            uuid not null references bidders(id),
  method               text not null check (method in ('cash', 'check', 'card_terminal')),
  amount_cents         integer not null check (amount_cents > 0),
  reference            text,                 -- check number / terminal receipt
  note                 text,
  received_by_admin_id uuid not null references admin_users(id),
  idempotency_key      text not null unique,
  created_at           timestamptz not null default now(),
  voided_at            timestamptz,
  voided_by_admin_id   uuid references admin_users(id),
  void_reason          text
);
create index payments_bidder_idx on payments (bidder_id);

create table payment_allocations (
  id                 uuid primary key default gen_random_uuid(),
  payment_id         uuid not null references payments(id),
  winning_result_id  uuid not null references winning_results(id),
  amount_cents       integer not null check (amount_cents > 0)
);
create index payment_alloc_result_idx on payment_allocations (winning_result_id);
create index payment_alloc_payment_idx on payment_allocations (payment_id);

create table item_collections (
  id                 uuid primary key default gen_random_uuid(),
  winning_result_id  uuid not null unique references winning_results(id),
  status             text not null default 'pending' check (status in ('pending', 'released')),
  released_by_admin_id uuid references admin_users(id),
  released_at        timestamptz,
  exception          boolean not null default false,
  exception_reason   text
);

create table audit_logs (
  id           bigint generated always as identity primary key,
  event_id     uuid references events(id),
  actor_type   text not null check (actor_type in ('admin', 'bidder', 'system')),
  actor_id     uuid,
  action       text not null,
  entity_type  text,
  entity_id    uuid,
  details      jsonb not null default '{}'::jsonb,
  created_at   timestamptz not null default now()
);
create index audit_logs_entity_idx on audit_logs (entity_type, entity_id);
create index audit_logs_created_idx on audit_logs (created_at desc);

-- ───────────────────────── immutability ─────────────────────────
create function forbid_mutation() returns trigger language plpgsql as $$
begin
  raise exception '% rows are immutable (% blocked)', tg_table_name, tg_op;
end $$;

create trigger silent_bids_immutable       before update or delete on silent_bids
  for each row execute function forbid_mutation();
create trigger live_accepted_bids_immutable before update or delete on live_accepted_bids
  for each row execute function forbid_mutation();
create trigger live_bid_voids_immutable    before update or delete on live_bid_voids
  for each row execute function forbid_mutation();
create trigger audit_logs_immutable        before update or delete on audit_logs
  for each row execute function forbid_mutation();

-- ───────────────────────── row-level security ─────────────────────────
-- The app talks to Postgres only from the server using the owner/service connection.
-- RLS is enabled with NO policies, so the Supabase anon/authenticated roles (and anyone
-- holding the public anon key) can read or write nothing. Contact info never leaves the server.
do $$
declare t text;
begin
  for t in select tablename from pg_tables where schemaname = 'public' and tablename <> 'schema_migrations'
  loop
    execute format('alter table %I enable row level security', t);
  end loop;
end $$;

insert into schema_migrations (name) values ('0001_init.sql') on conflict do nothing;

-- ════════════ 0002_pin_auth.sql ════════════
-- Guests sign back in with bidder number + 4-digit PIN (shown once at registration; staff can reset).
-- Email/phone are now plain contact records, so verification codes are gone.
alter table bidders
  add column pin_hash          text,
  add column pin_failed        integer not null default 0,
  add column pin_locked_until  timestamptz;

drop table verification_codes;

insert into schema_migrations (name) values ('0002_pin_auth.sql') on conflict do nothing;

